import sys
import json
import requests
from urllib.parse import quote

def load_cache():
    try:
        with open('geo.cache', 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def save_cache(cache):
    with open('geo.cache', 'w') as f:
        json.dump(cache, f)

def get_country(address):
    url = f'https://ipinfo.example.net/{quote(address)}/json'
    try:
        response = requests.get(url)
        if response.status_code == 200:
            data = response.json()
            return data.get('country', 'UNKNOWN')
        return 'UNKNOWN'
    except requests.RequestException:
        return 'UNKNOWN'

def main():
    cache = load_cache()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if line not in cache:
            country = get_country(line)
            if country != 'UNKNOWN':
                cache[line] = country
            print(f"{line}\t{country}")
    save_cache(cache)

if __name__ == "__main__":
    main()

import sys
import json
import os
import requests

CACHE_FILE = 'geo.cache'

def load_cache():
    if os.path.exists(CACHE_FILE):
        with open(CACHE_FILE, 'r') as f:
            return json.load(f)
    return {}

def save_cache(cache):
    with open(CACHE_FILE, 'w') as f:
        json.dump(cache, f)

def get_country(ip_address, cache):
    if ip_address in cache:
        return cache[ip_address]
    try:
        response = requests.get(f'https://ipinfo.example.net/{ip_address}/json')
        if response.status_code == 200:
            data = response.json()
            country = data.get('country', 'UNKNOWN')
            cache[ip_address] = country
            return country
    except Exception:
        pass
    return 'UNKNOWN'

def main():
    cache = load_cache()
    for line in sys.stdin:
        ip_address = line.strip()
        if ip_address:
            country = get_country(ip_address, cache)
            print(f'{ip_address}\t{country}')
    save_cache(cache)

if __name__ == '__main__':
    main()
